/**
 * Markdown handoff rendering and export.
 *
 * `handoff.md` is a *derived* artifact. SQLite is authoritative: nothing here
 * ever writes back into the database, and a stale file is never treated as the
 * source of truth.
 */
import { mkdirSync, renameSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { safePathSegment, sanitizeArrayForMarkdown, sanitizeForMarkdown } from "./util.js";
export const HANDOFF_DIR = ".opencode/state";
export function renderHandoff(data, sessionID) {
    const title = sanitizeForMarkdown(data.task?.title ?? "Untitled Task");
    const status = sanitizeForMarkdown(data.task?.status ?? "unknown");
    const updatedAt = sanitizeForMarkdown(data.updatedAt ?? "Unknown");
    const objective = sanitizeForMarkdown(data.task?.objective ?? "Not set");
    const summary = sanitizeForMarkdown(data.summary ?? "No summary recorded.");
    const sanitizedPlan = sanitizeArrayForMarkdown(data.currentPlan);
    const sanitizedCompleted = sanitizeArrayForMarkdown(data.completedSteps);
    const sanitizedNext = sanitizeArrayForMarkdown(data.nextSteps);
    const sanitizedBlockers = sanitizeArrayForMarkdown(data.blockers);
    const sanitizedFiles = sanitizeArrayForMarkdown(data.filesTouched);
    const sanitizedNotes = sanitizeArrayForMarkdown(data.notes);
    const currentPlan = sanitizedPlan.length > 0 ? sanitizedPlan.map((s, i) => `${i + 1}. ${s}`).join("\n") : "None recorded.";
    const completedSteps = sanitizedCompleted.length > 0 ? sanitizedCompleted.map((s) => `- [x] ${s}`).join("\n") : "None.";
    const nextSteps = sanitizedNext.length > 0 ? sanitizedNext.map((s) => `- [ ] ${s}`).join("\n") : "None.";
    const blockers = sanitizedBlockers.length > 0 ? sanitizedBlockers.map((b) => `- ⚠️ ${b}`).join("\n") : "None.";
    const filesTouched = sanitizedFiles.length > 0 ? sanitizedFiles.map((f) => `- 📄 ${f}`).join("\n") : "None recorded.";
    const notes = sanitizedNotes.length > 0 ? sanitizedNotes.map((n) => `- ${n}`).join("\n") : "None.";
    const sessionLine = sessionID ? `\n**Session:** ${sanitizeForMarkdown(sessionID)}` : "";
    return `# Handoff — ${title}

**Status:** ${status}
**Updated:** ${updatedAt}${sessionLine}
**Objective:** ${objective}

## Summary
${summary}

## Current Plan
${currentPlan}

## Completed Steps
${completedSteps}

## Next Steps
${nextSteps}

## Blockers
${blockers}

## Files Touched
${filesTouched}

## Notes
${notes}

---
*Generated by @gitdamnit/checkpoint-orchestrator. Do not edit manually.*
*Source of truth is the checkpoint-orchestrator SQLite database; this file is a derived export.*
*To continue: call \`checkpoint_load\` to restore full state.*
`;
}
/**
 * Session-scoped path. Session ids are sanitized so that exporting from two
 * sessions can never collide or escape the state directory.
 */
export function handoffFilePath(projectDirectory, sessionID, directory = HANDOFF_DIR) {
    return join(projectDirectory, directory, `handoff-${safePathSegment(sessionID)}.md`);
}
/** Atomic write: create the parent directory, write a temp file, then rename. */
export function writeHandoffFile(filePath, content) {
    mkdirSync(dirname(filePath), { recursive: true });
    const temp = `${filePath}.tmp-${process.pid}-${Date.now()}`;
    writeFileSync(temp, content, "utf8");
    renameSync(temp, filePath);
}
